command:
$ErrorActionPreference = 'Stop'
$workspaceRoot = 'D:\GitHub\Forge-Conductor-Windows-Edition'
. (Join-Path $workspaceRoot '.forge-codex\instructions\scripts\Common.ps1')
$evidenceRelative = '.forge-codex\state\evidence\P16\manager-host-transition-lifecycle-checkpoint.json'
$evidencePath = Join-Path $workspaceRoot $evidenceRelative
$evidence = Get-Content -Raw -LiteralPath $evidencePath | ConvertFrom-Json
$sourceProperties = @($evidence.source_sha256.PSObject.Properties)
if ($sourceProperties.Count -ne 8) { throw "Unexpected source hash count: $($sourceProperties.Count)" }
foreach ($property in $sourceProperties) {
    $actual = Get-FileSha256 -Path (Join-Path $workspaceRoot $property.Name)
    if ($actual -ne [string]$property.Value) { throw "Source hash mismatch: $($property.Name)" }
}
$binaryPaths = [ordered]@{
    'ForgeConductor.Manager.ProcessHostTests.exe' = 'out\build\windows-msvc-x64\bin\Release\ForgeConductor.Manager.ProcessHostTests.exe'
    'ForgeConductor.Manager.TransitionWorkerTests.exe' = 'out\build\windows-msvc-x64\bin\Release\ForgeConductor.Manager.TransitionWorkerTests.exe'
    'ForgeConductor.Manager.CompositionSupportTests.exe' = 'out\build\windows-msvc-x64\bin\Release\ForgeConductor.Manager.CompositionSupportTests.exe'
    'ForgeConductor.Manager.Host.lib' = 'out\build\windows-msvc-x64\lib\Release\ForgeConductor.Manager.Host.lib'
}
foreach ($entry in $binaryPaths.GetEnumerator()) {
    $actual = Get-FileSha256 -Path (Join-Path $workspaceRoot $entry.Value)
    if ($actual -ne [string]$evidence.binary_sha256.($entry.Key)) { throw "Binary hash mismatch: $($entry.Key)" }
}
$commandRecords = @(
    @('.forge-codex\state\commands\20260830T105300721Z-9ebe1366.json', [string]$evidence.recorded_build.command_record_sha256),
    @('.forge-codex\state\commands\20260830T105318136Z-e7176840.json', [string]$evidence.recorded_validation.command_record_sha256)
)
foreach ($record in $commandRecords) {
    if ((Get-FileSha256 -Path (Join-Path $workspaceRoot $record[0])) -ne $record[1]) { throw "Command-record hash mismatch: $($record[0])" }
}
$testRecord = Get-Content -Raw -LiteralPath (Join-Path $workspaceRoot $commandRecords[1][0]) | ConvertFrom-Json
if ([string]$testRecord.command -match '(-L|--label-regex)\s+G16') { throw 'Focused validation invoked the G16 label gate.' }
$testStdout = Get-Content -Raw -LiteralPath (Join-Path $workspaceRoot $testRecord.stdout)
if ($testStdout -notmatch '100% tests passed out of 3') { throw 'Focused validation did not report three passing tests.' }
$runState = Get-Content -Raw -LiteralPath (Join-Path $workspaceRoot '.forge-codex\state\run-state.json') | ConvertFrom-Json
$p16 = @($runState.phases | Where-Object id -eq 'P16')
$g16 = @($runState.gates | Where-Object id -eq 'G16')
if ($p16.Count -ne 1 -or $p16[0].status -ne 'in_progress') { throw 'P16 durable state is not in_progress.' }
if ($g16.Count -ne 1 -or $g16[0].status -ne 'not_started') { throw 'G16 durable state is not not_started.' }
if ($p16[0].evidence -notcontains $evidenceRelative.Replace('\','/')) { throw 'P16 durable state omits this checkpoint.' }
& (Join-Path $workspaceRoot '.forge-codex\instructions\scripts\Validate-NoPython.ps1') -WorkspaceRoot $workspaceRoot
& (Join-Path $workspaceRoot '.forge-codex\instructions\scripts\Validate-NoAttribution.ps1') -WorkspaceRoot $workspaceRoot
& (Join-Path $workspaceRoot '.forge-codex\instructions\scripts\Verify-Ledger.ps1') -WorkspaceRoot $workspaceRoot
$diffOutput = & git -C $workspaceRoot diff --check 2>&1
if ($LASTEXITCODE -ne 0) { throw "git diff --check failed: $diffOutput" }
$changedTextFiles = @($sourceProperties.Name) + $evidenceRelative
$strictUtf8 = [Text.UTF8Encoding]::new($false, $true)
foreach ($relative in $changedTextFiles) {
    $bytes = [IO.File]::ReadAllBytes((Join-Path $workspaceRoot $relative))
    if ($bytes.Length -ge 3 -and $bytes[0] -eq 0xef -and $bytes[1] -eq 0xbb -and $bytes[2] -eq 0xbf) { throw "UTF-8 BOM is forbidden: $relative" }
    $text = $strictUtf8.GetString($bytes)
    if ($text -match '(?<!\r)\n' -or $text -match '\r(?!\n)') { throw "Non-CRLF line ending: $relative" }
    foreach ($line in [regex]::Split($text, '\r\n')) { if ($line -match '[ \t]+$') { throw "Trailing whitespace: $relative" } }
}
Write-Output "Source hashes matched: $($sourceProperties.Count)"
Write-Output "Binary hashes matched: $($binaryPaths.Count)"
Write-Output "Command records matched: $($commandRecords.Count)"
Write-Output "Changed text files CRLF UTF-8 no BOM: $($changedTextFiles.Count)"
Write-Output 'Focused selection did not invoke the G16 label gate.'
Write-Output 'P16 in_progress and G16 not_started durable state verified.'
Write-Output 'git diff --check passed.'
exit 0
